#include "audio/CymbalEngine.h"
#include <cmath>
#include <iostream>
namespace { struct Metrics { float peak{}, left{}, right{}; }; Metrics renderHit(int model,float position) { cymbalforge::CymbalEngine engine; engine.prepare(48000,256); engine.parameters.model.store(model); engine.parameters.complexity.store(.85f); engine.parameters.shimmer.store(.75f); engine.strike(.95f,position); juce::AudioBuffer<float> buffer(2,256); Metrics result; for(int block=0;block<80;++block) { engine.render(buffer,0,256); for(int channel=0;channel<2;++channel) for(int sample=0;sample<256;++sample) { auto value=buffer.getSample(channel,sample); if(!std::isfinite(value)) return {}; result.peak=juce::jmax(result.peak,std::abs(value)); (channel==0?result.left:result.right)+=value*value; } } return result; } }
int main(){ auto crashBell=renderHit(0,.15f); auto crashEdge=renderHit(0,.88f); auto darkRide=renderHit(1,.60f); auto trash=renderHit(2,.60f); auto valid=[](const Metrics& m){return m.peak>.00001f && m.peak<8.0f && m.left>0 && m.right>0;}; if(!valid(crashBell)||!valid(crashEdge)||!valid(darkRide)||!valid(trash)){std::cerr<<"Engine produced invalid audio\n";return 1;} if(std::abs(crashBell.left-crashEdge.left)<.001f){std::cerr<<"Strike position did not change the response\n";return 1;} if(std::abs(darkRide.left-trash.left)<.001f){std::cerr<<"Cymbal family did not change the response\n";return 1;} if(std::abs(crashBell.left-crashBell.right)<.000001f){std::cerr<<"Stereo decorrelation missing\n";return 1;} std::cout<<"CymbalEngine spectral regression tests passed\n";return 0;}
